"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["72542"],{45625(e){e.exports=JSON.parse('{"id":"FIN-972","slug":"restructuring","term":"Restructuring","also_known_as":[],"difficulty":"Intermediate","definition":"Restructuring is a significant change to a company\'s finances, operations or organisation, often made to improve performance, reduce costs or deal with financial difficulty.","explanation":["Restructuring can take several forms. Financial restructuring changes a company\'s debts and capital, for example by renegotiating loans, extending repayment dates, swapping debt for equity or raising new money. Operational restructuring changes how the business works, such as closing facilities, cutting jobs, selling divisions or changing business processes. Organisational restructuring changes the management structure.","Companies restructure for various reasons. A struggling company with too much debt might restructure to avoid insolvency. A healthy company might restructure to adapt to changing markets, technology or competition.","For example, a retailer facing falling sales and heavy debt might close unprofitable stores, sell its online division and agree with lenders to convert part of its debt into shares, reducing its interest payments.","Restructuring can be carried out informally, through negotiation with lenders and stakeholders, or formally, through court-supervised processes such as Chapter 11 in the United States or restructuring plans and administration in the United Kingdom. Restructuring often involves difficult choices, including job losses and losses for shareholders and creditors, but can allow a viable business to survive."],"note":"","total":1500,"prev":{"slug":"restricted-stock-unit","term":"Restricted Stock Unit"},"next":{"slug":"retail-bank","term":"Retail Bank"}}')}}]);